    {
        JPopupMenu menu =
                new JPopupMenu();

        String displayName =
                getDisplayName(
                        normalizedName
                );

        boolean isCustomer =
                customers.containsKey(
                        normalizedName
                );

        boolean isHidden =
                isHidden(
                        normalizedName
                );

        JMenuItem playerTitle =
                new JMenuItem(
                        displayName
                );

        playerTitle.setEnabled(false);

        menu.add(playerTitle);
        menu.addSeparator();

        JMenuItem addKillItem =
                new JMenuItem(
                        "Add +1 Kill"
                );

        addKillItem.addActionListener(
                event ->
                        addPlayerKill(
                                normalizedName
                        )
        );

        JMenuItem removeKillItem =
                new JMenuItem(
                        "Remove -1 Kill"
                );

        removeKillItem.addActionListener(
                event ->
                        removePlayerKill(
                                normalizedName
                        )
        );

        JMenuItem resetKillItem =
                new JMenuItem(
                        "Reset Player KC"
                );

        resetKillItem.addActionListener(
                event ->
                        resetPlayerKillCount(
                                normalizedName
                        )
        );

        menu.add(addKillItem);
        menu.add(removeKillItem);
        menu.add(resetKillItem);
        menu.addSeparator();

        if (isCustomer)
        {
            JMenuItem removeCustomerItem =
                    new JMenuItem(
                            "Remove Customer"
                    );

            removeCustomerItem.addActionListener(
                    event ->
                            removeCustomer(
                                    normalizedName
                            )
            );

            menu.add(
                    removeCustomerItem
            );
        }
        else
        {
            JMenuItem setCustomerItem =
                    new JMenuItem(
                            "Set as Customer"
                    );

            setCustomerItem.addActionListener(
                    event ->
                            setCustomer(
                                    normalizedName
                            )
            );

            menu.add(
                    setCustomerItem
            );
        }

        JMenuItem packageSizeItem =
                new JMenuItem(
                        "Set Package Size"
                );

        packageSizeItem.addActionListener(
                event ->
                        setCustomerPackageSize(
                                normalizedName
                        )
        );

        JMenuItem addPackageKillItem =
                new JMenuItem(
                        "Add +1 Package Kill"
                );

        addPackageKillItem.addActionListener(
                event ->
                        addCustomerPackageKill(
                                normalizedName
                        )
        );

        JMenuItem resetPackageItem =
                new JMenuItem(
                        "Reset Package"
                );

        resetPackageItem.addActionListener(
                event ->
                        resetCustomerPackage(
                                normalizedName
                        )
        );

        JMenuItem completePackageItem =
                new JMenuItem(
                        "Mark Complete"
                );

        completePackageItem.addActionListener(
                event ->
                        markCustomerPackageComplete(
                                normalizedName
                        )
        );

        menu.add(packageSizeItem);
        menu.add(addPackageKillItem);
        menu.add(resetPackageItem);
        menu.add(completePackageItem);
        menu.addSeparator();

        if (isHidden)
        {
            JMenuItem unhideItem =
                    new JMenuItem(
                            "Unhide Player"
                    );

            unhideItem.addActionListener(
                    event ->
                            unhidePlayer(
                                    normalizedName
                            )
            );

            menu.add(unhideItem);
        }
        else
        {
            JMenuItem hideItem =
                    new JMenuItem(
                            "Hide Player"
                    );

            hideItem.addActionListener(
                    event ->
                            hidePlayer(
                                    normalizedName
                            )
            );

            menu.add(hideItem);
        }

        JMenuItem copyNameItem =
                new JMenuItem(
                        "Copy Name"
                );

        copyNameItem.addActionListener(
                event ->
                        copyPlayerName(
                                normalizedName
                        )
        );

        menu.add(copyNameItem);

        return menu;
    }
    private void addPlayerKill(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        if (giveKillCallback != null)
        {
            giveKillCallback.accept(
                    displayName
            );

            return;
        }

        String matchingKey =
                findKillCountKey(
                        normalizedName
                );

        killCountReference.put(
                matchingKey,
                killCountReference.getOrDefault(
                        matchingKey,
                        0
                ) + 1
        );

        refreshPlayerDisplay();
    }
    private void resetCustomerPackage(String normalizedName)
    {
        CustomerPackage customerPackage =
                customers.get(normalizedName);

        if (customerPackage == null)
        {
            return;
        }

        customerPackage.packageKills = 0;
        customerPackage.completed = false;

        refreshPlayerDisplay();
    }
    private void removePlayerKill(
            String normalizedName)
    {
        String key =
                findKillCountKey(
                        normalizedName
                );

        int currentKills =
                killCountReference.getOrDefault(
                        key,
                        0
                );

        if (currentKills <= 1)
        {
            killCountReference.remove(
                    key
            );
        }
        else
        {
            killCountReference.put(
                    key,
                    currentKills - 1
            );
        }

        refreshPlayerDisplay();
    }

    private void resetPlayerKillCount(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        int result =
                JOptionPane.showConfirmDialog(
                        this,
                        "Reset KC for " +
                                displayName +
                                "?",
                        "Reset Player KC",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.WARNING_MESSAGE
                );

        if (result !=
                JOptionPane.YES_OPTION)
        {
            return;
        }

        String key =
                findKillCountKey(
                        normalizedName
                );

        killCountReference.remove(
                key
        );

        refreshPlayerDisplay();
    }

    private void setCustomer(
            String normalizedName)
    {
        customers.computeIfAbsent(
                normalizedName,
                name ->
                        new CustomerPackage()
        );

        refreshPlayerDisplay();
    }

    private void removeCustomer(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        int result =
                JOptionPane.showConfirmDialog(
                        this,
                        "Remove " +
                                displayName +
                                " as a customer?",
                        "Remove Customer",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.QUESTION_MESSAGE
                );

        if (result !=
                JOptionPane.YES_OPTION)
        {
            return;
        }

        customers.remove(
                normalizedName
        );

        refreshPlayerDisplay();
    }

    private void setCustomerPackageSize(
            String normalizedName)
    {
        setCustomer(
                normalizedName
        );

        CustomerPackage customerPackage =
                customers.get(
                        normalizedName
                );

        String existingValue =
                customerPackage.packageSize > 0
                        ? String.valueOf(
                        customerPackage.packageSize
                )
                        : "";

        String input =
                JOptionPane.showInputDialog(
                        this,
                        "Enter package size for " +
                                getDisplayName(
                                        normalizedName
                                ) +
                                ":",
                        existingValue
                );

        if (input == null)
        {
            return;
        }

        input =
                input.trim();

        if (input.isEmpty())
        {
            return;
        }

        try
        {
            int packageSize =
                    Integer.parseInt(
                            input
                    );

            if (packageSize <= 0)
            {
                throw new NumberFormatException();
            }

            customerPackage.packageSize =
                    packageSize;

            customerPackage.completed =
                    customerPackage.packageKills >=
                            packageSize;

            refreshPlayerDisplay();
        }
        catch (NumberFormatException exception)
        {
            JOptionPane.showMessageDialog(
                    this,
                    "Package size must be a number greater than 0.",
                    "Invalid Package Size",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

    private void addCustomerPackageKill(
            String normalizedName)
    {
        setCustomer(normalizedName);

        CustomerPackage customerPackage =
                customers.get(normalizedName);

        /*
         * Remember whether it was already complete so the
         * chat message is sent only once.
         */
        boolean wasAlreadyCompleted =
                customerPackage.completed;

        customerPackage.packageKills++;

        if (customerPackage.packageSize > 0 &&
                customerPackage.packageKills >=
                        customerPackage.packageSize)
        {
            customerPackage.packageKills =
                    customerPackage.packageSize;

            customerPackage.completed = true;

            if (!wasAlreadyCompleted &&
                    packageCompleteCallback != null)
            {
                String playerName =
                        getDisplayName(normalizedName);

                packageCompleteCallback.accept(
                        "\"[WeCorp] Package Complete! \" " +
                                playerName +
                                " has finished their " +
                                customerPackage.packageSize +
                                "/" +
                                customerPackage.packageSize +
                                " KC package."
                );
            }
        }

        refreshPlayerDisplay();
    }

    private void markCustomerPackageComplete(
            String normalizedName)
    {
        setCustomer(
                normalizedName
        );

        CustomerPackage customerPackage =
                customers.get(
                        normalizedName
                );

        if (customerPackage.packageSize > 0)
        {
            customerPackage.packageKills =
                    customerPackage.packageSize;
        }

        customerPackage.completed =
                true;

        refreshPlayerDisplay();
    }

    private void hidePlayer(
            String normalizedName)
    {
        hiddenPlayersReference.add(
                normalizedName
        );

        refreshPlayerDisplay();
    }

    private void unhidePlayer(
            String normalizedName)
    {
        removeNormalizedName(
                hiddenPlayersReference,
                normalizedName
        );

        refreshPlayerDisplay();
    }

    private void showHiddenPlayersMenu()
    {
        JPopupMenu hiddenMenu =
                new JPopupMenu();

        List<String> hiddenNames =
                getNormalizedHiddenPlayers();

        if (hiddenNames.isEmpty())
        {
            JMenuItem emptyItem =
                    new JMenuItem(
                            "No hidden players"
                    );

            emptyItem.setEnabled(false);

            hiddenMenu.add(
                    emptyItem
            );
        }
        else
        {
            hiddenNames.sort(
                    Comparator.comparing(
                            this::getDisplayName
                    )
            );

            for (String normalizedName :
                    hiddenNames)
            {
                JMenuItem playerItem =
                        new JMenuItem(
                                "Unhide " +
                                        getDisplayName(
                                                normalizedName
                                        )
                        );

                playerItem.addActionListener(
                        event ->
                                unhidePlayer(
                                        normalizedName
                                )
                );

                hiddenMenu.add(
                        playerItem
                );
            }

            hiddenMenu.addSeparator();

            JMenuItem unhideAllItem =
                    new JMenuItem(
                            "Unhide All"
                    );

            unhideAllItem.addActionListener(
                    event ->
                    {
                        hiddenPlayersReference.clear();

                        refreshPlayerDisplay();
                    }
            );

            hiddenMenu.add(
                    unhideAllItem
            );
        }

        hiddenMenu.show(
                showHiddenButton,
                0,
                showHiddenButton.getHeight()
        );
    }

    private void copyPlayerName(
            String normalizedName)
    {
        String displayName =
                getDisplayName(
                        normalizedName
                );

        try
        {
            StringSelection selection =
                    new StringSelection(
                            displayName
                    );

            Toolkit
                    .getDefaultToolkit()
                    .getSystemClipboard()
                    .setContents(
                            selection,
                            selection
                    );
        }
        catch (IllegalStateException exception)
        {
            JOptionPane.showMessageDialog(
                    this,
                    "Could not copy the player name.",
                    "Copy Failed",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

