                        "Reset the full WeCorpCC trip?\n" +
                                "This clears KC, customers, packages and hidden players.",
                        "Reset Trip",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.WARNING_MESSAGE
                );

