        private PlayerRowData(
                String normalizedName,
                String displayName,
                String specText,
                int kills,
                boolean lowHp,
                boolean temporarilyAway,
                boolean away,
                long lastSeen)
        {
            this.normalizedName =
                    normalizedName;

            this.displayName =
