            JProgressBar progressBar,
            boolean complete)
    {
        progressBar.setForeground(
                complete
                        ? COMPLETE_COLOR
                        : INCOMPLETE_COLOR
        );
    }

    private void refreshTimer()
    {
        if (!preparationStarted ||
                prepStartTime <= 0)
        {
            prepTimeLabel.setText(
                    "0m 00s"
            );

            return;
        }

        long totalSeconds =
                (System.currentTimeMillis() -
                        prepStartTime) / 1000;

        long minutes =
                totalSeconds / 60;

        long seconds =
                totalSeconds % 60;

        prepTimeLabel.setText(
                String.format(
                        "%dm %02ds",
                        minutes,
                        seconds
                )
        );
    }
