                        "- 20 successful specs\n" +
                        "- Normal attacks don't count\n" +
                        "- Zero damage doesn't count\n\n" +

                        "READY TO KILL when all goals are complete.";

        JOptionPane.showMessageDialog(
                this,
                guide,
                "Solo Guide",
                JOptionPane.INFORMATION_MESSAGE
        );
    }
